import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.D1K3FKSn.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/guide/faq.html"}],["meta",{"property":"og:title","content":"FAQ | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/guide/faq.html"}],["meta",{"name":"twitter:title","content":"FAQ | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),n={name:"guide/faq.md"};function i(s,e,d,l,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="which-browsers-are-supported" tabindex="-1">Which browsers are supported? <a class="header-anchor" href="#which-browsers-are-supported" aria-label="Permalink to &quot;Which browsers are supported?&quot;">​</a></h2><p>Kiln requires WebGPU. Chrome/Edge 113+ and Safari 26+ support it out of the box. Firefox ships WebGPU by default in recent versions (141+), though support may be partial on some platforms — check <code>dom.webgpu.enabled</code> if needed. Make sure hardware acceleration is enabled in your browser settings.</p><p>If WebGPU is unavailable, <code>KilnViewer.create()</code> rejects with a descriptive error (e.g. &quot;WebGPU not supported&quot;) rather than failing silently — the demo viewer surfaces that message on the page instead of showing a blank canvas.</p><h2 id="can-kiln-read-my-data" tabindex="-1">Can Kiln read my data? <a class="header-anchor" href="#can-kiln-read-my-data" aria-label="Permalink to &quot;Can Kiln read my data?&quot;">​</a></h2><ul><li><strong>OME-Zarr (NGFF v0.4/v0.5)</strong> — compatible multiscale datasets load directly from a URL or local directory, with no Kiln-specific conversion. Input can be <code>uint8</code>, <code>uint16</code>, or <code>float32</code> (not signed integers or <code>float64</code>); <code>uint16</code> and <code>float32</code> are converted to <code>r16float</code> internally.</li><li><strong>Raw volumes</strong> (and other formats) are converted once to Kiln&#39;s compressed <a href="/data/sharded-binary.html">sharded binary format</a> with the bundled CLI, then streamed the same way.</li><li>Full requirements are in the <a href="/data/ome-zarr.html">Data Guide</a>.</li></ul><h2 id="why-won-t-my-dataset-load-from-s3-or-my-own-server" tabindex="-1">Why won&#39;t my dataset load from S3 or my own server? <a class="header-anchor" href="#why-won-t-my-dataset-load-from-s3-or-my-own-server" aria-label="Permalink to &quot;Why won&#39;t my dataset load from S3 or my own server?&quot;">​</a></h2><p>Almost always <strong>CORS</strong>. Kiln fetches data with cross-origin HTTP requests (including Range requests), so the bucket or server must return permissive CORS headers — <code>Access-Control-Allow-Origin</code>, and <code>Access-Control-Allow-Headers: Range</code> for sharded binary. See <a href="/data/hosting.html">Hosting for streaming</a> for the S3/CDN configuration.</p><h2 id="how-much-vram-does-kiln-use" tabindex="-1">How much VRAM does Kiln use? <a class="header-anchor" href="#how-much-vram-does-kiln-use" aria-label="Permalink to &quot;How much VRAM does Kiln use?&quot;">​</a></h2><p>Kiln uses a bounded GPU residency/atlas cache — ~1.3 GiB by default and configurable — for volume-residency resources (atlas texture + indirection table); this excludes render targets and other GPU allocations. See <a href="/architecture/memory-budget.html">Architecture</a> for the accounting.</p><h2 id="what-are-the-known-rendering-issues" tabindex="-1">What are the known rendering issues? <a class="header-anchor" href="#what-are-the-known-rendering-issues" aria-label="Permalink to &quot;What are the known rendering issues?&quot;">​</a></h2><p>LOD transitions can produce brief visual discontinuities while bricks stream in. Brick boundary seams may be faintly visible in isosurface (ISO) mode, where normal estimation samples across brick edges. See <a href="/reference/issues.html">Known Issues</a> for the current list.</p><h2 id="can-i-use-kiln-in-my-own-application" tabindex="-1">Can I use Kiln in my own application? <a class="header-anchor" href="#can-i-use-kiln-in-my-own-application" aria-label="Permalink to &quot;Can I use Kiln in my own application?&quot;">​</a></h2><p>Yes. Install <code>kiln-render</code> from npm and use <code>KilnViewer.create()</code> — see the <a href="/guide/quick-start.html">Quick start</a>. Kiln is Apache 2.0 licensed.</p>',14)])])}const p=a(n,[["render",i]]);export{m as __pageData,p as default};
